import express from 'express'
import Stripe from 'stripe'

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY)
const app = express()

// 1. webhook FIRST, with raw body
app.post('/webhooks/stripe', express.raw({ type: 'application/json' }), async (req, res) => {
  let event
  try {
    event = stripe.webhooks.constructEvent(
      req.body,                                  // Buffer
      req.get('stripe-signature'),
      process.env.STRIPE_WEBHOOK_SECRET
    )
  } catch (err) {
    console.error('Bad signature:', err.message)
    return res.status(400).send('Webhook signature verification failed')
  }

  if (event.type === 'checkout.session.completed') {
    const session = event.data.object
    await markOrderPaid(session.metadata.orderId, session.id)   // idempotent update
  }
  res.json({ received: true })
})

// 2. JSON parser for the rest of the API
app.use(express.json())

app.post('/api/checkout', async (req, res) => {
  const order = await loadOrderForUser(req.body.orderId)        // prices from DB
  const session = await stripe.checkout.sessions.create({
    mode: 'payment',
    line_items: order.items.map((i) => ({
      quantity: i.qty,
      price_data: {
        currency: 'inr',
        unit_amount: i.price * 100,                             // smallest unit
        product_data: { name: i.name },
      },
    })),
    metadata: { orderId: String(order.id) },
    success_url: `${process.env.CLIENT_URL}/success`,
    cancel_url: `${process.env.CLIENT_URL}/cart`,
  })
  res.json({ url: session.url })
})

app.listen(3000)

import cron from 'node-cron'
import User from './models/User.js'
import { sendEmail } from './utils/email.js'

let running = false

// every day at 02:00 India time: delete unverified accounts older than 3 days
cron.schedule('0 2 * * *', async () => {
  if (running) return                        // prevent overlap
  running = true
  try {
    const cutoff = new Date(Date.now() - 3 * 24 * 3600 * 1000)
    const { deletedCount } = await User.deleteMany({ isVerified: false, createdAt: { $lt: cutoff } })
    console.log(`[cron] removed ${deletedCount} unverified users`)
  } catch (err) {
    console.error('[cron] cleanup failed', err)
  } finally {
    running = false
  }
}, { timezone: 'Asia/Kolkata' })

// every Monday at 09:00: weekly digest
cron.schedule('0 9 * * 1', async () => {
  try {
    const users = await User.find({ digest: true }).select('email name')
    for (const u of users) await sendEmail(u.email, 'Your weekly digest', `Hi ${u.name}, here is your digest`)
  } catch (err) {
    console.error('[cron] digest failed', err)
  }
}, { timezone: 'Asia/Kolkata' })

console.log('Cron jobs scheduled')
